        unit: "Financial Mathematics",
        topic: "Interest and Depreciation",
        subtopic: "Share Tables",
        question: "Why should fees be included when comparing share investments?",
        answer: "Fees reduce the actual profit and can make an apparently profitable investment less worthwhile."
